inline const CrowdControlRow* crowd_control(int64_t guid) {
    const auto it = std::lower_bound(std::begin(kCrowdControls), std::end(kCrowdControls), guid, [](const CrowdControlRow& r, int64_t g) { return r.guid < g; });
    return it != std::end(kCrowdControls) && it->guid == guid ? it : nullptr;
}

